pub struct ActionMenu {
    pub is_open: bool,
    pub target: Option<MenuTarget>,
    pub actions: Vec<MenuAction>,
    pub state: ListState,
}

impl ActionMenu {
    pub fn new() -> Self {
        Self {
            is_open: false,
            target: None,
            actions: vec![],
            state: ListState::default(),
        }
    }

    pub fn open(&mut self, target: MenuTarget, route: &Route) {
        let mut dynamic_actions = Vec::new();

        match &target {
            MenuTarget::Track(t) => {
                dynamic_actions.push(MenuAction::PlayNow);
                dynamic_actions.push(MenuAction::AddToQueue);
                dynamic_actions.push(MenuAction::AddToPlaylist);
                if let Route::PlaylistDetail(_) = route {
