pub enum Event {
    Tick,
    Key(KeyEvent),
}

pub fn read(tick_rate: Duration) -> anyhow::Result<Event> {
    if event::poll(tick_rate)?
    && let CrosstermEvent::Key(key) = event::read()? {
        return Ok(Event::Key(key));
    }

    Ok(Event::Tick)
}

pub fn handle_album_events(key: KeyEvent, app: &mut App) {
    let mut target_to_open = None;

    if let Route::AlbumDetail(album_state) = &mut app.route {
        match key {
            KeyEvent{ code: KeyCode::Down, .. }
            | KeyEvent { code: KeyCode::Char('j'), ..}
            | KeyEvent {
                code: KeyCode::Char('d'),
                modifiers: KeyModifiers::CONTROL,
                ..
            } => {
                let steps = if key.code == KeyCode::Char('d') { 10 } else { 1 };
                album_state.tracks.next(steps, false);
            }

            KeyEvent { code: KeyCode::Up, .. }
            | KeyEvent { code: KeyCode::Char('k'), .. }
            | KeyEvent {
                code: KeyCode::Char('u'),
                modifiers: KeyModifiers::CONTROL,
                ..
            } => {
                let steps = if key.code == KeyCode::Char('u') { 10 } else { 1 };
                album_state.tracks.previous(steps, false);
            }

            KeyEvent { code: KeyCode::Char('t'), .. } => {
                target_to_open = album_state.tracks.state.selected()
                    .and_then(|idx| album_state.tracks.items.get(idx))
                    .map(|track| MenuTarget::Track(track.clone()));
            }

            KeyEvent { code: KeyCode::Backspace, .. }
            | KeyEvent { code: KeyCode::Char('b'), .. }
            | KeyEvent { code: KeyCode::Esc, .. } => {
                app.active_block = ActiveBlock::PlaylistsMenu;
            }

            _ => {}
        }
    }

    if let Some(target) = target_to_open {
        app.action_menu.open(target, &app.route);
    }
}

use crate::app::{ActiveBlock, App, route::Route};
use crate::network::models::*;
use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};

pub fn handle_global_events(key: KeyEvent, app: &mut App) -> bool {
    // -------------------------------------- quit ----------------------------------------
    if key.code == KeyCode::Char('q') 
        || (key.code == KeyCode::Char('c') && key.modifiers.contains(KeyModifiers::CONTROL)) 
    {
        app.should_quit = true;
        return true;
    }

    // ----------------------------------- playbar -------------------------------------
    if let Some(playback) = &mut app.playback {
        // pause/resume
        if key.code == KeyCode::Char(' ') {
            if app.track_ended {
                if let Some(item) = &playback.item {
                    let uri = match item {
                        PlayableItem::Track(t) => t.uri.clone(),
                        PlayableItem::Episode(e) => e.uri.clone(),
                    };
                    playback.is_playing = true;
                    playback.progress = Duration::from_millis(0);
                    app.track_ended = false;
                    let _ = app.network_tx.send(ClientRequest::Player {
                        request: PlayerRequest::Play(uri),
                        is_active_device: app.device_state.is_active_device()
                    });
                }
            } else {
                let is_playing = playback.is_playing;
                playback.is_playing = !is_playing;
                let _ = app.network_tx.send(ClientRequest::Player {
                    request: PlayerRequest::TogglePlayback(is_playing),
                    is_active_device: app.device_state.is_active_device()
                });
            }
            return true;
        }

        // volume
        if key.code == KeyCode::Char('-') {
            let vol = &mut playback.device.volume;
            *vol = vol.saturating_sub(5);
            let _ = app.network_tx.send(ClientRequest::Player {
                request: PlayerRequest::SetVolume(*vol),
                is_active_device: app.device_state.is_active_device()
            });
            return true;
        }
        if key.code == KeyCode::Char('+') {
            let vol = &mut playback.device.volume;
            *vol = vol.saturating_add(5).min(100);
            let _ = app.network_tx.send(ClientRequest::Player {
                request: PlayerRequest::SetVolume(*vol),
                is_active_device: app.device_state.is_active_device()
            });
            return true;
        }

        // next
        if key.code == KeyCode::Char('n') {
            let _ = app.network_tx.send(ClientRequest::Player {
                request: PlayerRequest::NextTrack,
                is_active_device: app.device_state.is_active_device()
            });
            return true;
        }

        // prev
        if key.code == KeyCode::Char('p') {
            let _ = app.network_tx.send(ClientRequest::Player {
                request: PlayerRequest::PreviousTrack,
                is_active_device: app.device_state.is_active_device()
            });
            return true;
        }

        // cycle repeat
        if key.code == KeyCode::Char('r') {
            let state = match playback.repeat_state {
                RepeatState::Off => RepeatState::Context,
                RepeatState::Context => RepeatState::Track,
                RepeatState::Track => RepeatState::Off,
            };
            playback.repeat_state = state;
            let _ = app.network_tx.send(ClientRequest::Player {
                request: PlayerRequest::SetRepeatMode(state),
                is_active_device: app.device_state.is_active_device()
            });
            return true;
        }

        // toggle shuffle
        if key.code == KeyCode::Char('s') {
            let shuffling = playback.shuffle_state;
            playback.shuffle_state = !shuffling;
            let _ = app.network_tx.send(ClientRequest::Player {
                request: PlayerRequest::ToggleShuffle(shuffling),
                is_active_device: app.device_state.is_active_device()
            });
            return true;
        }
    }

    // ----------------------------------- home -------------------------------------
    if key.code == KeyCode::Char('H') {
        if !matches!(app.route, Route::Home(_)) {
            app.set_current_route(Route::Home(HomeState::default())); 
        }
        app.active_block = ActiveBlock::HomeBlock;
        return true;
    }

    // ----------------------------------- search -----------------------------------
    if key.code == KeyCode::Char('S') {
        if !matches!(app.route, Route::Search(_)) {
            app.set_current_route(Route::Search(SearchState::default()));
        }
        app.active_block = ActiveBlock::SearchInput;
        return true;
    }

    // ------------------------------------ queue -----------------------------------
    if key.code == KeyCode::Char('Q') {
        if !matches!(app.route, Route::Queue(_)) {
            app.set_current_route(Route::Queue(QueueState::default()));
        }
        app.active_block = ActiveBlock::QueueBlock;
        return true;
    }

    // ------------------------------------- lyrics ----------------------------------
    if key.code == KeyCode::Char('L') {
        if !matches!(app.route, Route::Lyrics(_)) {
            app.set_current_route(Route::Lyrics(LyricsState::default()));
        }
        app.active_block = ActiveBlock::LyricsText;
        return true;
    }

    // ----------------------------------- active block -------------------------------
    if key.code == KeyCode::Tab && !key.modifiers.contains(KeyModifiers::CONTROL) {
        if app.active_block == ActiveBlock::SearchResults {
            return false;
        }

        app.active_block = match app.active_block {
            ActiveBlock::LibraryMenu => ActiveBlock::PlaylistsMenu,
            ActiveBlock::PlaylistsMenu => match app.route {
                Route::PlaylistDetail(_) => ActiveBlock::PlaylistTracks,
                Route::Search(_) => ActiveBlock::SearchInput,
                Route::Queue(_) => ActiveBlock::QueueBlock,
                Route::AlbumDetail(_) => ActiveBlock::AlbumBlock,

                Route::LikedSongs(_) => ActiveBlock::LikedSongs,
                Route::SavedAlbums(_) => ActiveBlock::SavedAlbums,
                Route::SavedArtists(_) => ActiveBlock::SavedArtists,
                Route::SavedPodcasts(_) => ActiveBlock::SavedPodcasts,
                _ => ActiveBlock::HomeBlock,
            },

            ActiveBlock::SearchInput => {
                if let Route::Search(ref mut search_state) = app.route {
                    search_state.hovered_pane = SearchHoveredPane::Tracks;
                }
                ActiveBlock::SearchResults
            },

            ActiveBlock::LyricsText => ActiveBlock::LyricsInfo,

            ActiveBlock::HomeBlock 
            | ActiveBlock::PlaylistTracks 
            | ActiveBlock::QueueBlock 
            | ActiveBlock::AlbumBlock
            | ActiveBlock::LikedSongs
            | ActiveBlock::SavedAlbums
            | ActiveBlock::SavedArtists
            | ActiveBlock::SavedPodcasts
            | ActiveBlock::LyricsInfo => {
                ActiveBlock::Playbar
            },

            ActiveBlock::Playbar => match app.route {
                Route::Search(_) => ActiveBlock::SearchInput,
                Route::Lyrics(_) => ActiveBlock::LyricsText,
                _ => ActiveBlock::LibraryMenu,
            },

            _ => {
                if matches!(app.route, Route::Lyrics(_)) {
                    ActiveBlock::LyricsText
                } else {
                    ActiveBlock::LibraryMenu
                }
            },
        };
        return true; 
    }

    // -------------------------------- number keys ----------------------------------
    match key.code {
        KeyCode::Char('1') => {
            match app.route {
                Route::Search(_) => {
                    app.active_block = ActiveBlock::SearchInput;
                }
                Route::Lyrics(_) => {
                    app.active_block = ActiveBlock::LyricsText;
                }
                _ => {
                    app.active_block = ActiveBlock::LibraryMenu;
                }
            }

        },
        KeyCode::Char('2') => {
            match app.route {
                Route::Search(_) => {
                    app.active_block = ActiveBlock::SearchResults;
                }
                Route::Lyrics(_) => {
                    app.active_block = ActiveBlock::LyricsInfo;
                }
                _ => {
                    app.active_block = ActiveBlock::PlaylistsMenu;
                }
            }
        },
        KeyCode::Char('3') => {
            match app.route {
                Route::Home(_) => {
                    app.active_block = ActiveBlock::HomeBlock;
                },
                Route::AlbumDetail(_) => {
                    app.active_block = ActiveBlock::AlbumBlock;
                },
                Route::PlaylistDetail(_) => {
                    app.active_block = ActiveBlock::PlaylistTracks;
                },
                Route::LikedSongs(_) => {
                    app.active_block = ActiveBlock::LikedSongs;
                },
                Route::SavedAlbums(_) => {
                    app.active_block = ActiveBlock::SavedAlbums;
                },
                Route::SavedArtists(_) => {
                    app.active_block = ActiveBlock::SavedArtists;
                },
                Route::SavedPodcasts(_) => {
                    app.active_block = ActiveBlock::SavedPodcasts;
                },
                Route::Queue(_) => {
                    app.active_block = ActiveBlock::QueueBlock;
                },
                Route::Lyrics(_) => {
                    app.active_block = ActiveBlock::Playbar;
                },
                Route::Search(_) => {
                    app.active_block = ActiveBlock::Playbar;
                }
                _ => {}
            }
        },
        KeyCode::Char('4') if !matches!(app.route, Route::Search(_) | Route::Lyrics(_)) => {
            app.active_block = ActiveBlock::Playbar;
        }

        _ => {}
    }

    if key.code == KeyCode::Char('?') {
        app.show_help = true;
        return true;
    }

    if key.code == KeyCode::Char('g') {
        app.show_quick_actions = true;
        return true;
    }

    false
}

use std::time::Duration;
use crate::app::{ActiveBlock, App, route::Route};
use crate::app::home_state::HomeState;
use crate::app::search_state::{SearchState, SearchHoveredPane};
use crate::app::queue_state::QueueState;
use crate::app::lyrics_state::LyricsState;
use crossterm::event::{KeyCode, KeyModifiers, KeyEvent};
use crate::network::request::{ClientRequest, PlayerRequest};
use crate::network::models::*;

pub fn handle_home_events(key: KeyEvent, app: &mut App) {
    let App { route, network_tx, action_menu, .. } = app;

    if let Route::Home(home_state) = route {
        match key {
            KeyEvent { code: KeyCode::Right, .. } | KeyEvent { code: KeyCode::Char('l'), .. } => {
                home_state.active_tab = match home_state.active_tab {
                    HomeTab::TopTracks => HomeTab::TopArtists,
                    HomeTab::TopArtists => HomeTab::RecentlyPlayed,
                    HomeTab::RecentlyPlayed => HomeTab::TopTracks,
                };
                match home_state.active_tab {
                    HomeTab::TopTracks if home_state.top_tracks.list.items.is_empty() => {
                        let _ = network_tx.send(ClientRequest::GetUserTopTracks {
                            time_range: TimeRange::ShortTerm,
                            limit: app.page_limit,
                            offset: 0,
                        });
                    }
                    HomeTab::RecentlyPlayed if home_state.recent_tracks.list.items.is_empty() => {
                        let _ = network_tx.send(ClientRequest::GetRecentlyPlayed {
                            limit: app.page_limit,
                            after: None,
                        });
                    }
                    HomeTab::TopArtists if home_state.top_artists.list.items.is_empty() => {
                        let _ = network_tx.send(ClientRequest::GetUserTopArtists {
                            time_range: TimeRange::ShortTerm,
                            limit: app.page_limit,
                            offset: 0,
                        });
                    }
                    _ => {}
                }
            }

            KeyEvent { code: KeyCode::Left, .. } | KeyEvent { code: KeyCode::Char('h'), .. } => {
                home_state.active_tab = match home_state.active_tab {
                    HomeTab::TopTracks => HomeTab::RecentlyPlayed,
                    HomeTab::TopArtists => HomeTab::TopTracks,
                    HomeTab::RecentlyPlayed => HomeTab::TopArtists,
                };
                match home_state.active_tab {
                    HomeTab::TopTracks if home_state.top_tracks.list.items.is_empty() => {
                        let _ = network_tx.send(ClientRequest::GetUserTopTracks {
                            time_range: TimeRange::ShortTerm,
                            limit: app.page_limit,
                            offset: 0,
                        });
                    }
                    HomeTab::RecentlyPlayed if home_state.recent_tracks.list.items.is_empty() => {
                        let _ = network_tx.send(ClientRequest::GetRecentlyPlayed {
                            limit: app.page_limit,
                            after: None,
                        });
                    }
                    HomeTab::TopArtists if home_state.top_artists.list.items.is_empty() => {
                        let _ = network_tx.send(ClientRequest::GetUserTopArtists {
                            time_range: TimeRange::ShortTerm,
                            limit: app.page_limit,
                            offset: 0,
                        });
                    }
                    _ => {}
                }
            }

            KeyEvent { code: KeyCode::Down, .. }
            | KeyEvent { code: KeyCode::Char('j'), .. }
            | KeyEvent {
                code: KeyCode::Char('d'),
                modifiers: KeyModifiers::CONTROL,
                ..
            } => {
                let threshold = 20;
                let steps = if key.code == KeyCode::Char('d') { 10 } else { 1 };

                match home_state.active_tab {
                    HomeTab::TopTracks => {
                        home_state.top_tracks.list.next(steps, false);

                        if let Some(selected) = home_state.top_tracks.list.state.selected()
                            && home_state.top_tracks.list.items.len() - selected <= threshold
                            && !home_state.top_tracks.is_loading
                            && !home_state.top_tracks.is_end
                        {
                            let _ = network_tx.send(ClientRequest::GetUserTopTracks {
                                time_range: TimeRange::ShortTerm,
                                limit: app.page_limit,
                                offset: home_state.top_tracks.list.items.len() as u32,
                            });
                            home_state.top_tracks.is_loading = true;
                        }
                    }
                    HomeTab::TopArtists => {
                        home_state.top_artists.list.next(steps, false);

                        if let Some(selected) = home_state.top_artists.list.state.selected()
                            && home_state.top_artists.list.items.len() - selected <= threshold
                            && !home_state.top_artists.is_loading
                            && !home_state.top_artists.is_end
                        {
                            let _ = network_tx.send(ClientRequest::GetUserTopArtists {
                                time_range: TimeRange::ShortTerm,
                                limit: app.page_limit,
                                offset: home_state.top_artists.list.items.len() as u32,
                            });
                            home_state.top_artists.is_loading = true;
                        }
                    }
                    // Currently this endpoint works with a time-based cursor, while we only
                    // handle index-based and id-based cursor for now
                    HomeTab::RecentlyPlayed => home_state.recent_tracks.list.next(steps, false),
                }
            }

            KeyEvent { code: KeyCode::Up, .. }
            | KeyEvent { code: KeyCode::Char('k'), .. }
            | KeyEvent {
                code: KeyCode::Char('u'),
                modifiers: KeyModifiers::CONTROL,
                ..
            } => {
                let steps = if key.code == KeyCode::Char('u') { 10 } else { 1 };
                match home_state.active_tab {
                    HomeTab::TopTracks => home_state.top_tracks.list.previous(steps, false),
                    HomeTab::TopArtists => home_state.top_artists.list.previous(steps, false),
                    HomeTab::RecentlyPlayed => home_state.recent_tracks.list.previous(steps, false)
                }
            }

            KeyEvent { code: KeyCode::Char('t'), .. } => {
                let target = match home_state.active_tab {
                    HomeTab::TopTracks => home_state
                        .top_tracks
                        .list
                        .state
                        .selected()
                        .and_then(|idx| home_state.top_tracks.list.items.get(idx))
                        .map(|t| MenuTarget::Track(t.clone())),
                    HomeTab::RecentlyPlayed => home_state
                        .recent_tracks
                        .list
                        .state
                        .selected()
                        .and_then(|idx| home_state.recent_tracks.list.items.get(idx))
                        .map(|t| MenuTarget::Track(t.clone())),
                    HomeTab::TopArtists => home_state
                        .top_artists
                        .list
                        .state
                        .selected()
                        .and_then(|idx| home_state.top_artists.list.items.get(idx))
                        .map(|a| MenuTarget::Artist(a.clone())),
                };

                if let Some(t) = target {
                    action_menu.open(t, route);
                }
            }
            _ => {}
        }
    }
}

use crate::app::{App, route::Route, home_state::HomeTab};
use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use crate::ClientRequest;
use crate::network::models::*;

pub fn handle_key_events(key: KeyEvent, app: &mut App) {
    if app.show_help {
        app.show_help = false;
        return;
    }

    if app.show_quick_actions {
        match key.code {
            KeyCode::Char('h') => {
                app.set_current_route(Route::Home(HomeState::default()));
                app.active_block = ActiveBlock::HomeBlock;
            }
            KeyCode::Char('s') => {
                app.set_current_route(Route::Search(SearchState::default()));
                app.active_block = ActiveBlock::SearchInput;
            }
            KeyCode::Char('t') if !app.show_device_selector => {
                let _ = app.network_tx.send(ClientRequest::GetDevices);
                app.show_device_selector = true;
            }
            _ => {}
        }
        app.show_quick_actions = false;
        return;
    }

    if app.playlist_selector.is_open {
        match key.code {
            KeyCode::Esc => {
                app.playlist_selector.close();
            }
            KeyCode::Down | KeyCode::Char('j') => {
                app.playlist_selector.next();
            }
            KeyCode::Up | KeyCode::Char('k') => {
                app.playlist_selector.previous();
            }
            KeyCode::Enter => {
                execute_add_to_playlist(app);
                app.playlist_selector.close();
                app.action_menu.close();
            }
            _ => {}
        }
        return;
    }

    if app.action_menu.is_open {
        match key.code {
            KeyCode::Esc | KeyCode::Char('t') => {
                app.action_menu.close();
            }
            KeyCode::Down | KeyCode::Char('j') => {
                app.action_menu.next();
            }
            KeyCode::Up | KeyCode::Char('k') => {
                app.action_menu.previous();
            }
            KeyCode::Enter => {
                if execute_action_menu_command(app) {
                    app.action_menu.close();
                }
            }
            _ => {}
        }
        return;
    }

    if app.show_device_selector {
        match key.code {
            KeyCode::Down | KeyCode::Char('j') => {
                app.device_state.online_devices.next(1, false);
            }
            KeyCode::Up | KeyCode::Char('k') => {
                app.device_state.online_devices.previous(1, false);
            }
            KeyCode::Enter => {
                let selecting_active_device = |selected_idx: usize| if let Some(idx) = app.device_state.active_device_idx() {
                    selected_idx == idx
                } else {
                    false
                };
                if let Some(idx) = app.device_state.online_devices.state.selected()
                && !selecting_active_device(idx) {
                    app.device_state.online_devices.state.select(Some(idx));
                    let _ = app.network_tx.send(ClientRequest::TransferPlayback {
                        device_id: app.device_state.device_id_from_idx(idx),
                        should_play: false
                    });
                    // Fetch devices again to ensure active device is updated
                    let _ = app.network_tx.send(ClientRequest::GetDevices);

                    app.show_device_selector = false;
                }
            }
            _ => {
                app.show_device_selector = false;
            }
        }
        return;
    }

    if app.active_block == ActiveBlock::SearchInput {
        search::handle_search_events(key, app);
        return;
    }
    // global keyboard
    if global::handle_global_events(key, app) {
        return;
    }

    // each active_block
    match app.active_block {
        ActiveBlock::PlaylistsMenu | ActiveBlock::LibraryMenu => {
            sidebar::handle_sidebar_events(key, app);
        }
        ActiveBlock::HomeBlock => {
            home::handle_home_events(key, app);
            // No return here to allow route-specific tab logic below
        }
        ActiveBlock::PlaylistTracks => {
            playlist::handle_playlist_events(key, app);
        }
        ActiveBlock::SearchResults => {
            search::handle_search_events(key, app);
        }
        ActiveBlock::QueueBlock => {
            queue::handle_queue_events(key, app);
        }
        ActiveBlock::AlbumBlock => {
            album::handle_album_events(key, app);
        }
        ActiveBlock::LikedSongs => {
            library::handle_liked_songs_events(key, app);
        }
        ActiveBlock::SavedAlbums => {
            library::handle_saved_albums_events(key, app);
        }
        ActiveBlock::SavedArtists => {
            library::handle_saved_artists_events(key, app);
        }
        ActiveBlock::SavedPodcasts => {
            library::handle_saved_podcasts_events(key, app);
        }
        ActiveBlock::Playbar => {
            playbar::handle_playbar_events(key, app);
        }
        ActiveBlock::LyricsText => {
            lyrics::handle_lyrics_events(key, app);
        }
        _ => {}
    }
}

// TODO: handle the AddToPlaylist action outside the function and
// return nothing here
fn execute_action_menu_command(app: &mut App) -> bool {
    let selected_action = app.action_menu.state.selected()
        .and_then(|idx| app.action_menu.actions.get(idx));

    if let (Some(action), Some(target)) = (selected_action, &app.action_menu.target) {
        let uri = match target {
            MenuTarget::Track(t) => Some(t.uri.clone()),
            MenuTarget::Episode(e) => Some(e.uri.clone()),
            MenuTarget::Artist(a) => Some(a.uri.clone()),
            MenuTarget::Album(a) => Some(a.uri.clone()),
            MenuTarget::Playlist(p) => Some(p.uri.clone()),
        };

        match action {
            MenuAction::PlayNow => {
                if let Some(u) = uri {
                    let player_req = match target {
                        // If this is a playable item and we are in a playlist/album then
                        // playing the item will also play the whole collection
                        MenuTarget::Track(_) | MenuTarget::Episode(_) => {
                            match &app.route {
                                Route::PlaylistDetail(s) => {
                                    let index = s.tracks.state.selected().map(|i| i as u32);
                                    let context_options = app.playback.as_ref()
                                        .map(|pb| pb.to_librespot_options(false));
                                    let opts = LoadRequestOptions {
                                        start_playing: true,
                                        playing_track: index.map(PlayingTrack::Index),
                                        context_options,
                                        ..Default::default()
                                    };
                                    PlayerRequest::PlayContext(s.playlist.uri.clone(), opts)
                                }
                                Route::AlbumDetail(s) => {
                                    let index = s.tracks.state.selected().map(|i| i as u32);
                                    let context_options = app.playback.as_ref()
                                        .map(|pb| pb.to_librespot_options(false));
                                    let opts = LoadRequestOptions {
                                        start_playing: true,
                                        playing_track: index.map(PlayingTrack::Index),
                                        context_options,
                                        ..Default::default()
                                    };
                                    PlayerRequest::PlayContext(s.album.uri.clone(), opts)
                                }
                                _ => PlayerRequest::Play(u),
                            }
                        }
                        MenuTarget::Album(_) | MenuTarget::Playlist(_) | MenuTarget::Artist(_) => {
                            let context_options = app.playback.as_ref()
                                .map(|pb| pb.to_librespot_options(false));
                            let opts = LoadRequestOptions {
                                start_playing: true,
                                context_options,
                                ..Default::default()
                            };
                            PlayerRequest::PlayContext(u, opts)
                        }
                    };

                    let _ = app.network_tx.send(ClientRequest::Player {
                        request: player_req,
                        is_active_device: app.device_state.is_active_device()
                    });

                    if let Route::Queue(_) = &app.route {
                        let _ = app.network_tx.send(ClientRequest::GetQueue);
                    }
                }
                true
            }
            MenuAction::AddToQueue => {
                if let Some(u) = uri {
                    let _ = app.network_tx.send(ClientRequest::Player {
                        request: PlayerRequest::AddItemToQueue(u),
                        is_active_device: app.device_state.is_active_device()
                    });
                }
                true
            }
            MenuAction::AddToPlaylist => {
                let my_id = &app.user.id;

                let writable_playlists: Vec<Playlist> = app.playlists_menu.items
                    .iter()
                    .filter(|p| {
                        let is_owner = p.owner.id == *my_id;
                        let is_collaborator = p.collaborative;

                        is_owner || is_collaborator
                    })
                    .cloned()
                    .collect();

                if !writable_playlists.is_empty() {
                    app.playlist_selector.playlists = writable_playlists;
                    app.playlist_selector.is_open = true;
                    app.playlist_selector.state.select(Some(0));

                    false
                } else {
                    true
                }
            }
            MenuAction::RemoveFromThisPlaylist => {
                if let Route::PlaylistDetail(route) = &mut app.route
                    && let Some(uri) = uri && !uri.is_empty() {
                    let _ = app.network_tx.send(ClientRequest::RemoveItemsFromPlaylist {
                        playlist_id: route.playlist.id.clone(), uris: vec![uri.clone()]
                    });
                    // Update the list locally
                    route.tracks.items.retain(|item| match item {
                        PlayableItem::Track(i) => i.uri != uri,
                        PlayableItem::Episode(i) => i.uri != uri
                    });
                    // Fix the selected index
                    if let Some(idx) = route.tracks.state.selected() {
                        let len = route.tracks.items.len();
                        if idx >= len {
                            route.tracks.state.select(Some(len - 1));
                        }
                    }

                }
                true
            }
            MenuAction::GoToAlbum => {
                let album_id = match target {
                    MenuTarget::Track(t) => t.album.as_ref().map(|a| a.id.clone()),
                    MenuTarget::Album(a) => Some(a.id.clone()),
                    _ => None,
                };

                if let Some(id) = album_id {
                    let new_album_state = AlbumState::new(id);
                    app.set_current_route(Route::AlbumDetail(new_album_state));
                    app.active_block = ActiveBlock::AlbumBlock;
                }
                true
            }
            MenuAction::ViewDetails => {
                // TODO
                true
            }
            MenuAction::GoToShow => {
                true
            }
            MenuAction::SaveToLibrary => {
                if let Some(uri) = uri && !uri.is_empty() {
                    match target {
                        MenuTarget::Track(_) => {
                            let _ = app.network_tx
                                .send(ClientRequest::SaveItemsToLibrary(vec![uri]));
                        }
                        MenuTarget::Album(_) => {
                            let _ = app.network_tx
                                .send(ClientRequest::SaveItemsToLibrary(vec![uri]));
                        }
                        MenuTarget::Artist(_) => {
                            let _ = app.network_tx
                                .send(ClientRequest::SaveItemsToLibrary(vec![uri]));
                        }
                        MenuTarget::Episode(_) => {
                            let _ = app.network_tx
                                .send(ClientRequest::SaveItemsToLibrary(vec![uri]));
                        }
                        _ => {}
                    }
                }
                true
            }
            #[allow(clippy::collapsible_if)]
            MenuAction::RemoveFromLibrary => {
                if let Some(uri) = uri && !uri.is_empty() {
                    if matches!(target, MenuTarget::Track(_))
                    || matches!(target, MenuTarget::Album(_))
                    || matches!(target, MenuTarget::Artist(_))
                    || matches!(target, MenuTarget::Episode(_)) {
                        let _ = app.network_tx
                            .send(ClientRequest::RemoveItemsFromLibrary(vec![uri.clone()]));
                        // Update the list locally
                        let state_info = match &mut app.route {
                            Route::LikedSongs(s) => {
                                s.tracks.items.retain(|item| item.uri != uri);
                                Some((s.tracks.items.len(), &mut s.tracks.state))
                            }
                            Route::SavedAlbums(s) => {
                                s.albums.items.retain(|item| item.uri != uri);
                                Some((s.albums.items.len(), &mut s.albums.state))
                            }
                            Route::SavedArtists(s) => {
                                s.artists.items.retain(|item| item.uri != uri);
                                Some((s.artists.items.len(), &mut s.artists.state))
                            }
                            Route::SavedPodcasts(s) => {
                                s.podcasts.items.retain(|item| item.uri != uri);
                                Some((s.podcasts.items.len(), &mut s.podcasts.state))
                            }
                            _ => None
                        };
                        // Fix the selected index
                        if let Some((len, list_state)) = state_info
                        && let Some(idx) = list_state.selected()
                        && idx >= len {
                            list_state.select(Some(len - 1));
                        }
                    }
                }
                true
            }
            MenuAction::FollowArtist => {
                if let MenuTarget::Artist(_) = target && let Some(uri) = uri {
                    let _ = app.network_tx.send(ClientRequest::SaveItemsToLibrary(vec![uri]));
                }
                true
            }
            MenuAction::UnfollowArtist => {
                if let MenuTarget::Artist(_) = target && let Some(uri) = uri {
                    let _ = app.network_tx.send(ClientRequest::RemoveItemsFromLibrary(vec![uri]));
                }
                true
            }
        }
    } else {
        true
    }
}

fn execute_add_to_playlist(app: &mut App) {
    if let (Some(idx), Some(target)) = (
        app.playlist_selector.state.selected(),
        &app.action_menu.target
    ) {
        let playlist_id = app.playlist_selector.playlists[idx].id.clone();
        let uri = match target {
            MenuTarget::Track(t) => Some(t.uri.clone()),
            MenuTarget::Episode(e) => Some(e.uri.clone()),
            _ => None,
        };

        if let Some(u) = uri {
            let _ = app.network_tx.send(ClientRequest::AddItemsToPlaylist {
                playlist_id,
                uris: vec![u],
            });
        }
    }
}

use crate::app::{ActiveBlock, App, Route};
use crate::app::home_state::HomeState;
use crate::app::search_state::SearchState;
use crate::handlers::{album, library, playbar, queue, search, sidebar, lyrics};
use crate::network::models::*;
use crate::network::request::{PlayerRequest, ClientRequest};
use crossterm::event::{KeyEvent, KeyCode};

use super::{global, home, playlist};
use crate::app::types::MenuAction;

use crate::app::album_state::AlbumState;

use librespot_connect::{LoadRequestOptions, PlayingTrack};

pub fn handle_liked_songs_events(key: KeyEvent, app: &mut App) {
    let mut target_to_open = None;

    if let Route::LikedSongs(liked_songs) = &mut app.route {
        match key {
            KeyEvent{ code: KeyCode::Down, .. }
            | KeyEvent { code: KeyCode::Char('j'), ..}
            | KeyEvent {
                code: KeyCode::Char('d'),
                modifiers: KeyModifiers::CONTROL,
                ..
            } => {
                let steps = if key.code == KeyCode::Char('d') { 10 } else { 1 };
                liked_songs.tracks.next(steps, false);
                let threshold = 20;

                if let Some(selected) = liked_songs.tracks.state.selected()
                    && liked_songs.tracks.items.len() - selected <= threshold
                    && !liked_songs.is_loading
                    && !liked_songs.is_end {
                    let _ = app.network_tx.send(ClientRequest::GetUserLikedSongs {
                        limit: app.page_limit,
                        offset: liked_songs.tracks.items.len() as u32
                    });

                    liked_songs.is_loading = true;
                }
            }

            KeyEvent { code: KeyCode::Up, .. }
            | KeyEvent { code: KeyCode::Char('k'), .. }
            | KeyEvent {
                code: KeyCode::Char('u'),
                modifiers: KeyModifiers::CONTROL,
                ..
            } => {
                let steps = if key.code == KeyCode::Char('u') { 10 } else { 1 };
                liked_songs.tracks.previous(steps, false);
            }

            KeyEvent { code: KeyCode::Char('t'), .. } => {
