            PlayingTrack::Index(idx) => Self::Index(idx),
            PlayingTrack::Uri(uri) => Self::Uri(uri.to_string()),
            _ => Self::Index(0)
        }
    }
}

fn from(value: PlayingTrack) -> Self {
