// ------------------------------------------- Device Selector ------------------------------------
pub fn draw_device_selector(f: &mut Frame, app: &mut App, area: Rect) {
    let device_count = app.device_state.online_devices.items.len().max(1) as u16;
    let popup_height = (device_count + 2).min(area.height);

    let vertical_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Min(0),
            Constraint::Length(popup_height),
            Constraint::Min(0),
        ])
        .split(area);

    let percent_x = 45;
    let horizontal_layout = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(vertical_layout[1]);

    let popup_area = horizontal_layout[1];
    app.device_state.last_area = popup_area;

    // Explicitly expand the clear area so the text does not eat up the border
    let clear_x = popup_area.x.saturating_sub(2);
    let clear_width = popup_area.width.saturating_add(4);
    let clear_area = Rect {
        x: clear_x,
        y: popup_area.y,
        width: if clear_x + clear_width > area.right() { area.right() - clear_x } else { clear_width },
        height: popup_area.height,
    };

    f.render_widget(Clear, clear_area);

    let block = Block::default()
        .title(" Devices ")
        .title_alignment(Alignment::Center)
        .borders(Borders::ALL)
        .border_type(BorderType::Plain)
        .border_style(Style::default().fg(Color::LightCyan))
        .style(Style::default().bg(Color::Rgb(28, 28, 28)).fg(Color::White));

    let active_idx = app.device_state.active_device_idx();
    let local_idx = app.device_state.local_device_idx;

    let items: Vec<ListItem> = if app.device_state.online_devices.items.is_empty() {
        vec![ListItem::new(" No devices found")]
    } else {
        app.device_state
            .online_devices
            .items
            .iter()
            .enumerate()
            .map(|(i, d)| {
                let name = if d.name.is_empty() { "Unknown device" } else { d.name.as_str() };

                let icon = match d.r#type.to_lowercase().as_str() {
                    "computer" | "desktop" | "laptop" | "pc" => "💻",
                    "phone" | "smartphone" | "mobile" => "📱",
                    "speaker" | "audio" => "🔊",
                    _ => "❓",
                };

                let is_active = active_idx == Some(i);
                let is_local = local_idx == Some(i);

                let mut suffix = String::new();
                if is_local {
                    suffix.push_str(" [Local]");
                }
                if is_active {
                    suffix.push_str(" [Current]");
                }

                let content = format!(" {} {}{}", icon, name, suffix);
                let mut item = ListItem::new(content);

                item = item.style(Style::default().fg(Color::White));

                item
            })
            .collect()
    };

    let list = List::new(items)
        .block(block)
        .highlight_style(
            Style::default()
                .bg(Color::Rgb(50, 50, 50))
                .fg(Color::LightGreen)
                .add_modifier(Modifier::BOLD)
        )
        .highlight_symbol("> ")
        .highlight_spacing(HighlightSpacing::Always);

    f.render_stateful_widget(
        list,
        popup_area,
        &mut app.device_state.online_devices.state,
    );
}

pub fn draw(f: &mut Frame, state: &mut QueueState, active_block: &ActiveBlock, area: Rect) {
    let is_focused = *active_block == ActiveBlock::QueueBlock;
    let border_color = if is_focused { Color::LightCyan } else { Color::White };

    let block = Block::default()
        .title(" [3] Queue ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(border_color));

    let inner_area = block.inner(area);
    f.render_widget(block, area);

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(5),
            Constraint::Min(0),
        ])
        .split(inner_area);

    // --------------------------------------- Now Playing -----------------------------
    let now_playing_content = if let Some(item) = &state.currently_playing {
        let (icon, sub_label, sub_value) = match item {
            PlayableItem::Track(t) => (
                "🎵", 
                "💿 Album: ", 
                t.album.as_ref().map(|a| a.name.as_str()).unwrap_or("Unknown Album")
            ),
            PlayableItem::Episode(e) => (
                "🎙️", 
                "📺 Show: ", 
                if e.show_name.is_empty() { "Unknown Show" } else { &e.show_name }
            ),
        };

        vec![
            Line::from(vec![
                Span::styled(format!(" {} Now Playing: ", icon), Style::default().fg(Color::LightGreen).add_modifier(Modifier::BOLD)),
                Span::styled(format!("{} - {}", item.name(), item.artists()), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            ]),
            Line::from(vec![
                Span::raw(format!("    {}", sub_label)),
                Span::styled(sub_value.to_string(), Style::default().fg(Color::DarkGray)),
            ]),
        ]
    } else {
        vec![Line::from(Span::styled("   (Queue is empty)", Style::default().fg(Color::DarkGray)))]
    };

    let now_playing_widget = Paragraph::new(now_playing_content)
        .block(Block::default().padding(Padding::new(1, 1, 1, 0)));
    f.render_widget(now_playing_widget, chunks[0]);

    let table_block = Block::default()
        .title(" Up Next ")
        .borders(Borders::TOP)
        .border_style(Style::default().fg(border_color));

    let table_area = table_block.inner(chunks[1]);
    state.last_area = table_area;

    let table_width = table_area.width;
    let show_extra_column = table_width > 60;

    let header_style = Style::default().fg(Color::DarkGray).add_modifier(Modifier::BOLD);
    let highlight_style = if is_focused {
        Style::default().fg(Color::LightMagenta).add_modifier(Modifier::BOLD)
    } else {
        Style::default()
    };

    let (header_cells, widths) = if show_extra_column {
        (
            vec![" #title", "#artist / show", "#length"],
            vec![Constraint::Percentage(45), Constraint::Percentage(35), Constraint::Percentage(20)]
        )
    } else {
        (
            vec![" #title", "#artist / show"],
            vec![Constraint::Percentage(55), Constraint::Percentage(45)]
        )
    };

    let (title_max, artist_max) = if show_extra_column {
        (
            ((table_width as f32 * 0.45) as u16).saturating_sub(6),
            ((table_width as f32 * 0.35) as u16).saturating_sub(2),
        )
    } else {
        (
            ((table_width as f32 * 0.55) as u16).saturating_sub(6),
            ((table_width as f32 * 0.45) as u16).saturating_sub(2),
        )
    };

    let header = Row::new(header_cells).style(header_style).bottom_margin(0);

    let rows: Vec<Row> = state.queue_items.items.iter().enumerate().map(|(i, item)| {
        let title = truncate(item.name(), title_max);
        let artist = truncate(&item.artists(), artist_max);

        let duration = match item {
            PlayableItem::Track(t) => t.duration,
            PlayableItem::Episode(e) => e.duration,
        };
        let duration_str = format!("{}:{:02}", duration.as_secs() / 60, duration.as_secs() % 60);

        let icon = match item {
            PlayableItem::Track(_) => "󰎆",
            PlayableItem::Episode(_) => "",
        };

        if show_extra_column {
            Row::new(vec![
                format!("  {} {}. {}", icon, i + 1, title),
                artist,
                duration_str,
            ]).style(Style::default().fg(Color::White))
        } else {
            Row::new(vec![
                format!("  {} {}. {}", icon, i + 1, title),
                artist,
            ]).style(Style::default().fg(Color::White))
        }
    }).collect();

    let table_block = Block::default()
        .title(" Up Next ")
        .borders(Borders::TOP)
        .border_style(Style::default().fg(border_color));

    let table = Table::new(rows, widths)
        .header(header)
        .block(table_block)
        .highlight_symbol(if is_focused { "▶ " } else { "  " })
        .highlight_spacing(HighlightSpacing::Always)
        .row_highlight_style(highlight_style);

    f.render_stateful_widget(table, chunks[1], &mut state.queue_items.state);
}

use crate::app::{ActiveBlock, queue_state::QueueState};
use crate::network::models::*;
use ratatui::{
    Frame,
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Table, Row, HighlightSpacing, Paragraph, Padding},
};
use super::layout::truncate;

pub fn draw(f: &mut Frame, app: &mut App, area: Rect) {
    let (input_text, hovered_pane) = if let Route::Search(s) = &app.route {
        (s.input.clone(), s.hovered_pane.clone())
    } else {
        (String::new(), SearchHoveredPane::Input)
    };

    let is_input_active = app.active_block == ActiveBlock::SearchInput;
    let is_results_active = app.active_block == ActiveBlock::SearchResults;

    let main_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Length(3), Constraint::Min(0)])
        .split(area);

    // input
    let input_color = if is_input_active { Color::LightCyan } else { Color::White };

    let input_widget = Paragraph::new(input_text.clone()).block(
        Block::default()
            .title(if is_input_active {" 🔍 Search "} else {" [1] 🔍 Search "})
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(Style::default().fg(input_color))
            .padding(Padding::horizontal(1)),
    );
    f.render_widget(input_widget, main_chunks[0]);

    if is_input_active {
        f.set_cursor_position((
            main_chunks[0].x + 2 + input_text.chars().count() as u16,
            main_chunks[0].y + 1,
        ));
    }

    // grid
    let results_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Min(0)])
        .split(main_chunks[1]);

    let mut right_area = results_chunks[1];
    right_area.x = right_area.x.saturating_sub(1);
    right_area.width += 1;

    let mut queue_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Ratio(1, 3), 
            Constraint::Ratio(1, 3), 
            Constraint::Min(0),
        ])
        .split(right_area)
        .to_vec();

    queue_chunks[1].y = queue_chunks[1].y.saturating_sub(1);
    queue_chunks[1].height += 1;

    queue_chunks[2].y = queue_chunks[2].y.saturating_sub(1);
    queue_chunks[2].height += 1;

    let (tracks_area, artists_area, albums_area, playlists_area) = match hovered_pane {
        SearchHoveredPane::Artists => (
            queue_chunks[2],   
            results_chunks[0], 
            queue_chunks[0],   
            queue_chunks[1],   
        ),
        SearchHoveredPane::Albums => (
            queue_chunks[1],   
            queue_chunks[2],   
            results_chunks[0], 
            queue_chunks[0],   
        ),
        SearchHoveredPane::Playlists => (
            queue_chunks[0],   
            queue_chunks[1],   
            queue_chunks[2],   
            results_chunks[0], 
        ),
        _ => ( 
            results_chunks[0], 
            queue_chunks[0],   
            queue_chunks[1],   
            queue_chunks[2],   
        ),
    };

    // get data
    let search_state = if let Route::Search(ref s) = app.route {
        s
    } else {
        return;
    };

    let get_color = |pane: SearchHoveredPane| {
        if is_results_active && hovered_pane == pane {
            Color::LightCyan
        } else {
            Color::White
        }
    };

    let get_highlight_style = |pane: SearchHoveredPane| {
        if is_results_active && hovered_pane == pane {
            Style::default().fg(Color::LightMagenta).add_modifier(Modifier::BOLD)
        } else {
            Style::default()
        }
    };

    let get_highlight_symbol = |pane: SearchHoveredPane| {
        if is_results_active && hovered_pane == pane {
            "▶ "
        } else {
            "  "
        }
    };

    let build_block = |title: &str, pane: SearchHoveredPane| {
        let is_big_pane = match hovered_pane {
            SearchHoveredPane::Artists => pane == SearchHoveredPane::Artists,
            SearchHoveredPane::Albums => pane == SearchHoveredPane::Albums,
            SearchHoveredPane::Playlists => pane == SearchHoveredPane::Playlists,
            _ => pane == SearchHoveredPane::Tracks,
        };

        let prefix = if is_big_pane && !is_input_active { "[2] " } else { "" };

        Block::default()
            .title(format!(" {}{} ", prefix, title))
            .borders(Borders::ALL)
            .border_type(BorderType::Plain) 
            .border_style(Style::default().fg(get_color(pane)))
    };

    // tracks
    let track_max_width = tracks_area.width.saturating_sub(6);
    let tracks_items: Vec<ListItem> = search_state
        .tracks_state
        .items
        .iter()
        .map(|t| {
            let artist_names = t.artists.iter()
                .map(|a| a.name.as_str())
                .collect::<Vec<_>>()
                .join(", ");

            let full_text = format!("{} - {}", t.name, artist_names);
            ListItem::new(format!("  {}", truncate(&full_text, track_max_width)))
        })
    .collect();

    let tracks_list = List::new(tracks_items)
        .block(build_block("Tracks", SearchHoveredPane::Tracks))
        .highlight_style(get_highlight_style(SearchHoveredPane::Tracks))
        .highlight_symbol(get_highlight_symbol(SearchHoveredPane::Tracks))
        .highlight_spacing(HighlightSpacing::Always);

    // artists
    let artist_max_width = artists_area.width.saturating_sub(6);
    let artists_items: Vec<ListItem> = search_state
        .artists_state
        .items
        .iter()
        .map(|a| ListItem::new(format!("  {}", truncate(&a.name, artist_max_width))))
        .collect();

    let artists_list = List::new(artists_items)
        .block(build_block("Artists", SearchHoveredPane::Artists))
        .highlight_style(get_highlight_style(SearchHoveredPane::Artists))
        .highlight_symbol(get_highlight_symbol(SearchHoveredPane::Artists))
        .highlight_spacing(HighlightSpacing::Always);

    // albums
    let album_max_width = albums_area.width.saturating_sub(6);
    let albums_items: Vec<ListItem> = search_state
        .albums_state
        .items
        .iter()
        .map(|a| {
            let date = a.release_date.as_deref().unwrap_or("Unknown");
            let full_text = format!("{} ({})", a.name, date);
            ListItem::new(format!("  {}", truncate(&full_text, album_max_width)))
        })
    .collect();

    let albums_list = List::new(albums_items)
        .block(build_block("Albums", SearchHoveredPane::Albums))
        .highlight_style(get_highlight_style(SearchHoveredPane::Albums))
        .highlight_symbol(get_highlight_symbol(SearchHoveredPane::Albums))
        .highlight_spacing(HighlightSpacing::Always);

    // playlists
    let playlist_max_width = playlists_area.width.saturating_sub(6);
    let playlists_items: Vec<ListItem> = search_state
        .playlists_state
        .items
        .iter()
        .map(|p| {
            let full_text = format!("{} by {}", p.name, p.owner.display_name);
            ListItem::new(format!("  {}", truncate(&full_text, playlist_max_width)))
        })
    .collect();

    let playlists_list = List::new(playlists_items)
        .block(build_block("Playlists", SearchHoveredPane::Playlists))
        .highlight_style(get_highlight_style(SearchHoveredPane::Playlists))
        .highlight_symbol(get_highlight_symbol(SearchHoveredPane::Playlists))
        .highlight_spacing(HighlightSpacing::Always);

    if let Route::Search(ref mut search_state) = app.route {
        // store last area
        search_state.last_area = match search_state.hovered_pane {
            SearchHoveredPane::Tracks => tracks_area,
            SearchHoveredPane::Artists => artists_area,
            SearchHoveredPane::Albums => albums_area,
            SearchHoveredPane::Playlists => playlists_area,
            _ => main_chunks[1],
        };

        let mut lists = (Some(tracks_list), Some(artists_list), Some(albums_list), Some(playlists_list));

        if tracks_area != results_chunks[0] { f.render_stateful_widget(lists.0.take().unwrap(), tracks_area, &mut search_state.tracks_state.state); }
        if artists_area != results_chunks[0] { f.render_stateful_widget(lists.1.take().unwrap(), artists_area, &mut search_state.artists_state.state); }
        if albums_area != results_chunks[0] { f.render_stateful_widget(lists.2.take().unwrap(), albums_area, &mut search_state.albums_state.state); }
        if playlists_area != results_chunks[0] { f.render_stateful_widget(lists.3.take().unwrap(), playlists_area, &mut search_state.playlists_state.state); }

        if let Some(w) = lists.0.take() { f.render_stateful_widget(w, tracks_area, &mut search_state.tracks_state.state); }
        if let Some(w) = lists.1.take() { f.render_stateful_widget(w, artists_area, &mut search_state.artists_state.state); }
        if let Some(w) = lists.2.take() { f.render_stateful_widget(w, albums_area, &mut search_state.albums_state.state); }
        if let Some(w) = lists.3.take() { f.render_stateful_widget(w, playlists_area, &mut search_state.playlists_state.state); }
    }
}

use crate::app::{App, ActiveBlock, route::Route};
use crate::app::search_state::SearchHoveredPane;
use ratatui::{
    Frame,
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    widgets::{Block, Borders, BorderType, Paragraph, List, ListItem, Padding, HighlightSpacing},
};
use super::layout::truncate;

pub fn draw(f: &mut Frame, app: &mut App, area: Rect) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Length(6), Constraint::Min(0)])
        .split(area);

    draw_library(f, app, chunks[0]);
    draw_playlists(f, app, chunks[1]);
}

// library
fn draw_library(f: &mut Frame, app: &mut App, area: Rect) {
    let is_focused = app.active_block == ActiveBlock::LibraryMenu;
    let border_color = if is_focused { Color::LightCyan } else { Color::White };
    // Only highlight the selected item when the block is focused
    let highlight_style = if is_focused {
        Style::default()
            .fg(Color::Cyan)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default()
    };

    let items = vec![
        ListItem::new(" ♥ Liked Songs"),
        ListItem::new(" 👤 Artists"),
        ListItem::new(" 💿 Albums"),
        ListItem::new(" 🎙 Podcasts"),
    ];

    let list = List::new(items)
        .block(
            Block::default()
                .title(" [1] Library ")
                .borders(Borders::ALL)
                .border_style(Style::default().fg(border_color)),
        )
        .highlight_style(
            highlight_style
        );

    f.render_stateful_widget(list, area, &mut app.library_menu.state);
}

// playlists
fn draw_playlists(f: &mut Frame, app: &mut App, area: Rect) {
    let is_focused = app.active_block == ActiveBlock::PlaylistsMenu;
    let border_color = if is_focused { Color::LightCyan } else { Color::White };
    // Only highlight the selected item when the block is focused
    let highlight_style = if is_focused {
        Style::default()
            .fg(Color::Cyan)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default()
    };
    let mut rows: Vec<Row> = vec![];

    for playlist in &app.playlists_menu.items {
        rows.push(Row::new(vec![format!(" ♪ {}", playlist.name)]));
    }

    if rows.is_empty() {
        rows.push(Row::new(vec![" ⏳ Loading...".to_string()]));
    }

    let table = Table::new(rows, [Constraint::Percentage(100)])
        .block(
            Block::default()
                .title(" [2] Playlists ")
                .borders(Borders::ALL)
                .border_style(Style::default().fg(border_color)),
        )
        .row_highlight_style(
            highlight_style
        );

    f.render_stateful_widget(table, area, &mut app.playlists_menu.state);
}

use crate::app::{ActiveBlock, App};
use ratatui::{
    Frame,
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    widgets::{Block, Borders, List, ListItem, Table, Row},
};

pub fn draw(f: &mut Frame, _state: &SplashState, area: Rect) {
    let canvas = Canvas::default()
        .x_bounds([0.0, 100.0])
        .y_bounds([0.0, 100.0])
        .paint(|ctx| {
            let symbols = ["♫", "♪", "♩", "♬", ".", "°"];

            for i in 0..40 {
                let x = ((i * 137) % 100) as f64;
                let y = ((i * 331) % 100) as f64;

                let symbol = symbols[i % symbols.len()];

                // Trộn 2 màu xám để nốt nhạc ẩn nhẹ vào nền
                let color = if i % 2 == 0 { Color::DarkGray } else { Color::Gray };

                ctx.print(x, y, ratatui::text::Span::styled(symbol, Style::default().fg(color)));
            }
        });
    f.render_widget(canvas, area);

    let logo = [
        "  ███████  ███████   ███████  ████████ ████████ ██    ██  ",
        " ██     ██ ██    ██ ██     ██    ██       ██     ██  ██   ",
        " ██        ██    ██ ██     ██    ██       ██      ████    ",
        "  ███████  ███████  ██     ██    ██       ██       ██     ",
        "        ██ ██       ██     ██    ██       ██       ██     ",
        " ██     ██ ██       ██     ██    ██       ██       ██     ",
        "  ███████  ██        ███████     ██       ██       ██     ",
    ].join("\n");

    let vertical_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage(35), 
            Constraint::Length(7),      
            Constraint::Min(0),
        ])
        .split(area);

    let horizontal_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Min(0),
            Constraint::Length(65),
            Constraint::Min(0),
        ])
        .split(vertical_chunks[1]);

    let splash_text = Paragraph::new(logo)
        .style(Style::default().fg(Color::LightBlue));

    f.render_widget(Clear, horizontal_chunks[1]);
    f.render_widget(splash_text, horizontal_chunks[1]);
}

